// FeedCookMeasure / FeedCook over a REGION root — a locked builder's AsConst, a
// region FeedLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t FeedCookMeasure( const Feed * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FeedCookMeasureFrom( ctx, *root, allocator );
}

inline bool FeedCook( const Feed * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return FeedCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t FeedCookMeasure( const FeedBuilder & builder )
{
    if ( builder.region != NULL ) { return FeedCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedCookMeasureFrom( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool FeedCook( const FeedBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return FeedCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedCookFrom( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
// A pointer FIELD is a TableRef — eight bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( __is_trivially_copyable( Header ), "Header must stay relocatable" );
static_assert( __is_standard_layout( Header ), "Header must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Chunk ), "Chunk must stay relocatable" );
static_assert( __is_standard_layout( Chunk ), "Chunk must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Feed ), "Feed must stay relocatable" );
static_assert( __is_standard_layout( Feed ), "Feed must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( Header ) == 24, "Header's sizeof moved: the build version was taken over 24, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Header ) == 4, "Header's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Header, name ) == 0, "Header's field name moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Chunk ) == 48, "Chunk's sizeof moved: the build version was taken over 48, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Chunk ) == 8, "Chunk's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, data ) == 0, "Chunk's field data moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, next ) == 16, "Chunk's field next moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, links ) == 24, "Chunk's field links moved: the build version was taken over offset 24 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Feed ) == 120, "Feed's sizeof moved: the build version was taken over 120, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Feed ) == 8, "Feed's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, id ) == 0, "Feed's field id moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, frame ) == 8, "Feed's field frame moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, parts ) == 64, "Feed's field parts moved: the build version was taken over offset 64 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, pair ) == 104, "Feed's field pair moved: the build version was taken over offset 104 (docs/SPEC-TABLES.md §20.3)" );

